//! Original retained CURRENT readbacks after actual native Candidate training
//! and independent NoUpdate Evaluation. Existing same-process transports and
//! explicit test issuers remain fixtures. Readback-origin proof is not a Root
//! or daemon restart, and this test performs no ordinary C execution.

use std::sync::Arc;

use pretty_assertions::assert_eq;
use pretty_assertions::assert_ne;

use super::*;
use crate::OriginalCircuitLearningReadOwnerV1;
use crate::circuit_feature_current::original_learning_read_fixture as read_transport;

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn evaluated_retained_current_reads_fresh_and_cold_original_owners() -> anyhow::Result<()> {
    let mut f = Box::pin(PublicationFixture::ready()).await?;
    let context = f.context()?;
    assert_eq!(context.snapshot(), f.evaluation.snapshot());
    assert_eq!(&context.snapshot().receipts[2], f.training.receipt());
    assert_eq!(
        f.evaluation.training_attestation(),
        f.training.attestation()
    );
    assert!(context.snapshot().training_no_update_v2().is_none());
    assert!(matches!(
        f.training.receipt().observation,
        LearningIterationObservationV1::Training { .. }
    ));
    assert!(matches!(
        f.evaluation.receipt().observation,
        LearningIterationObservationV1::Evaluation {
            disposition: LearningEvaluationDispositionV1::NoUpdate,
            ..
        }
    ));
    assert_ne!(f.bundle.digest()?, f.host.original.candidate.digest()?);
    let source_before = f.host.original.predecessor_bytes()?;
    let b_before = f.host.upstream_files()?;
    let evaluation_before = f.host.original_files()?;
    let nonces = f.host.original.version.authority.capacity()?.used_nonces;
    let (trainer, evaluator, peers) = f.clients()?;
    let prepared = Box::pin(prepare_original_circuit_evaluated_retention_v1(
        context,
        trainer,
        evaluator,
        f.inputs()?,
    ))
    .await?;
    assert_eq!(
        prepared.final_use_binding().destination_id,
        "agentd.cell-generation.next-task-same-model"
    );
    let signed = f.host.original.version.sign(prepared.final_use_binding())?;
    let (task, trainer, evaluator) = prepared
        .publish_and_retain_original_evidence(signed)
        .await?;
    assert_ne!(f.source_a.scope.run_id, task.source().scope.run_id);
    let mut c = f.start_c(task).await?;
    assert_eq!(c.cell.snapshot(&f.source_c.scope)?.revision, 0);
    let baseline = f.bundle.digest()?;
    let publication_before = f.publication_bytes()?;
    let c_paths = [
        "q24-source.journal",
        "q24-source.witness",
        "q24-cell.journal",
        "q24-cell.witness",
    ]
    .map(|name| c.runtime.identity.home_root.join(name));
    let c_before = c_paths
        .iter()
        .map(std::fs::read)
        .collect::<std::io::Result<Vec<_>>>()?;
    let mut previous_read = None;
    for readback in [false, true] {
        let context = || -> anyhow::Result<crate::OriginalCircuitEvaluatedLearningReadContextV1> {
            let original = if readback {
                f.readback_context()?
            } else {
                f.context()?
            };
            Ok(
                crate::OriginalCircuitEvaluatedLearningReadContextV1::for_original_selection(
                    original,
                )?,
            )
        };
        let owner = Arc::new(
            OriginalCircuitLearningReadOwnerV1::from_original_evaluated_owners(
                c.cell.clone(),
                c.source.as_ref().clone(),
                c.runtime.identity.clone(),
                context()?,
            )?,
        );
        let (client, server) = read_transport::evaluated_client(context()?)?;
        let peer = read_transport::serve(owner, server);
        let first = client.read_current().await?;
        assert!(matches!(
            first.observation(),
            LearningIterationObservationV1::Selection { candidate_bundle, .. }
                if *candidate_bundle == baseline
        ));
        assert_eq!(client.read_current().await?, first);
        if let Some(previous) = previous_read.replace(first.clone()) {
            assert_eq!(previous, first);
        }
        drop(client);
        assert_eq!(peer.join().expect("original CURRENT read peer")?, 2);
    }
    assert_eq!(trainer.readback().await?, f.training);
    assert_eq!(evaluator.readback().await?, f.evaluation);
    drop(trainer);
    drop(evaluator);
    assert_eq!(peers.finish()?, [5, 5]);
    assert_eq!(
        f.host.original.version.authority.capacity()?.used_nonces,
        nonces + 1
    );
    assert_eq!(c.cell.snapshot(&f.source_c.scope)?.revision, 0);
    assert_eq!(f.publication_bytes()?, publication_before);
    assert_eq!(
        c_paths
            .iter()
            .map(std::fs::read)
            .collect::<std::io::Result<Vec<_>>>()?,
        c_before
    );
    assert_eq!(f.host.original.predecessor_bytes()?, source_before);
    assert_eq!(f.host.upstream_files()?, b_before);
    assert_eq!(f.host.original_files()?, evaluation_before);
    c.stop().await?;
    drop(c);
    f.finish().await
}

//! The canonical evaluated read profile consumes actual opaque T/B results.
//! Fresh/cold publication origins remain distinct before explicit read-only
//! conversion. This private fixture neither exports fields nor grants work.

use pretty_assertions::assert_eq;

use super::*;
use crate::OriginalCircuitLearningReadContextV1;
use crate::OriginalCircuitRetainedPublicationErrorV1;

pub(crate) fn check_evaluated_profiles(
    fresh: OriginalCircuitEvaluatedRetentionContextV1,
    cold: OriginalCircuitEvaluatedRetentionContextV1,
    evaluation_expires_at: u64,
) -> anyhow::Result<()> {
    let at = now()?;
    // The original publication distinction is preserved before conversion.
    fresh.require_new_original_receipt(at)?;
    assert!(matches!(
        cold.require_new_original_receipt(at),
        Err(OriginalCircuitRetainedPublicationErrorV1::Binding(
            "recovered evaluated retention is read-only"
        ))
    ));
    let (scope, verifier, training_evidence) = fresh.receipt_configuration();
    let expired = training_evidence
        .expires_at
        .max(evaluation_expires_at)
        .saturating_add(1);
    let mut legacy = OriginalCircuitLearningReadContextV1 {
        prefix: fresh.snapshot().clone(),
        scope,
        verifier,
        training_evidence,
        selection_evidence: None,
    };
    let fresh = OriginalCircuitEvaluatedLearningReadContextV1::for_original_selection(fresh)?;
    let cold = OriginalCircuitEvaluatedLearningReadContextV1::for_original_selection(cold)?;
    for profile in [&fresh, &cold] {
        let OriginalCut::Selection(original) = &profile.original else {
            anyhow::bail!("Selection input became a NextUse capability");
        };
        assert!(matches!(
            original.require_new_original_receipt(at),
            Err(OriginalCircuitRetainedPublicationErrorV1::Binding(
                "recovered evaluated retention is read-only"
            ))
        ));
    }
    let fresh = ReadProfile::Evaluated(fresh);
    let cold = ReadProfile::Evaluated(cold);
    let binding = fresh.binding(at)?;
    // The public Selection read factory attenuates both origins to the same
    // read-only purpose; neither retains fresh publication or receipt authority.
    assert_eq!(binding, cold.binding(at)?);
    assert_eq!(fresh.mode()?, wire::Mode::Selection);
    assert_eq!(cold.mode()?, wire::Mode::Selection);
    assert_eq!(fresh.decision()?.snapshot(), fresh.prefix());
    assert_eq!(fresh.prefix(), cold.prefix());
    assert!(fresh.legacy().is_err());
    assert!(cold.legacy().is_err());

    let request = fresh.request(binding, /*request_id*/ 1)?;
    fresh.require_request(&request, binding, /*request_id*/ 1)?;
    cold.require_request(&request, binding, /*request_id*/ 1)?;
    let value = serde_json::to_value(&request)?;
    for (field, replacement) in [
        ("schema", serde_json::json!(2)),
        ("operation", serde_json::json!(wire::OPERATION)),
        ("request_id", serde_json::json!(2)),
        (
            "binding",
            serde_json::json!(Digest32::of_bytes(b"other-proof").to_string()),
        ),
        (
            "prefix_head",
            serde_json::json!(Digest32::of_bytes(b"other-cut").to_string()),
        ),
        ("operation_id", serde_json::json!("other-source-operation")),
        ("mode", serde_json::json!("next_use")),
    ] {
        let mut changed = value.clone();
        changed[field] = replacement;
        let changed: wire::Request = serde_json::from_value(changed)?;
        assert!(matches!(
            fresh.require_request(&changed, binding, /*request_id*/ 1),
            Err(Error::Binding("original fixed evaluated read request"))
        ));
    }
    let mut injected = value;
    injected["execute"] = serde_json::json!(true);
    assert!(serde_json::from_value::<wire::Request>(injected).is_err());

    // The public legacy DTO cannot relabel CandidateTraining/Evaluation as
    // TrainingNoUpdate, including a fabricated extra Selector hint.
    assert!(wire::context_binding(&legacy, at).is_err());
    legacy.selection_evidence = Some(legacy.training_evidence.clone());
    assert!(wire::context_binding(&legacy, at).is_err());
    assert!(fresh.binding(expired).is_err());
    assert!(cold.binding(expired).is_err());
    Ok(())
}
